#!/usr/bin/env bash
# apply-payout-requirements.sh
# Shows contractors (and you) exactly what Stripe still needs before payouts work.
# Run:  bash ~/freddy-fixit/apply-payout-requirements.sh
set -euo pipefail
cd ~/freddy-fixit
rm -f .git/index.lock
TMPB64="$(mktemp)"
trap 'rm -f "$TMPB64"' EXIT

wf() {  # wf <relative-path>  (base64 body on stdin)
  mkdir -p "$(dirname "$1")"
  cat > "$TMPB64"
  base64 -d "$TMPB64" > "$1" 2>/dev/null || base64 -D -i "$TMPB64" -o "$1"
  echo "   wrote $1"
}

echo "==> Syncing with GitHub..."
git fetch -q origin
git checkout -q main
git reset -q --hard origin/main

echo "==> Writing files..."
